    },
    // The default site for your app. This value will be used when a siteRef could not be determined from the url
    defaultSite: 'ZimmermannAU',
    // Provide aliases for your sites. These will be used in place of your site id when generating paths throughout the application.
    // AU has no alias — it is the defaultSite and showDefaults: false keeps it at the root (/).
    siteAliases: {
      ZimmermannUK: 'uk',
      ZimmermannUS: 'us',
      ZimmermannUSIntl: 'en-ca',
      // EU domestic: one PWA site per locale prefix — all backed by SFCC ZimmermannEU (see sites.js)
      ZimmermannEUen: 'en-eu',
      ZimmermannEUfr: 'fr-eu',
      ZimmermannEUit: 'it-eu',
      ZimmermannEUes: 'es-eu',
      ZimmermannEUIntl: 'en-ch',
      ZimmermannHK: 'hk',
